                elif (n not in visited and grid[n[0]][n[1]] == '.' and grid[pos[0]][pos[1]] == '.'):
                    next_step = n
                    break
            if next_step:
                return ({n for n in next_pos if n!= next_step}, path[:-1] + [n] + [pos], [next_step])
    return visited, path, [next_pos[0]]

