import random

def solve(nums, k):
    def partition(lo, hi):
        pivot = nums[random.randint(lo, hi)]
        i = j = lo
        while i <= j:
            while nums[i] < pivot: i += 1
            while nums[j] > pivot: j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        return j

    def select(lo, hi, k):
        if lo == hi: return nums[lo]
        j = partition(lo, hi)
        if k == j+1: return nums[j]
        if k < j+1: return select(lo, j, k)
        return select(j+1, hi, k)

    return select(0, len(nums)-1, k)
