        if left < n and nums[left] > nums[largest]:
            largest = left

        if right < n and nums[right] > nums[largest]:
            largest = right

        if largest!= i:
            nums[i], nums[largest] = nums[largest], nums[i]
            heapify(nums, n, largest)

    def heapify_all(nums):
        n = len(nums)
        for i in range(n // 2 - 1, -1, -1):
            heapify(nums, n, i)

    def extract_min(nums):
        n = len(nums)
        if n == 0:
            return None
        min_val = nums[0]
        nums[0] = nums[n-1]
        nums[n-1] = None
        heapify(nums, n-1, 0)
        return min_val

    heapify_all(nums)
    for _ in range(k-1):
        _ = extract_min(nums)
    return extract_min(nums)
