def sum_array(left, right, arr):
    length = right - left + 1
    return sum([arr[left], arr[-(length - 1 - (left + 1)) + 1], (right - left) // 2 * (arr[left + 1] + arr[right])])

def check(left, mid, right, arr, n):
    score = sum_array(left, mid - 1, arr) + sum_array(mid + 1, right, arr) - 2 * sum_array(mid, mid, arr)
    return score >= n + 1

def binary_search(left, right, arr, n):
    while left <= right and left <= n and right >= 1:
        mid = (left + right) >> 1
        if check(left, mid, right, arr, n):
            right = mid - 1
        else:
            left = mid + 1
    if check(left, left, right, arr, n):
        return True
    return False
