def solve(nums):
    def flood_fill(matrix, row, col, value):
        if not (0 <= row < len(matrix) and 0 <= col < len(matrix[0])):
            return
        if matrix[row][col]!= value:
            return

        matrix[row][col] = -1

        flood_fill(matrix, row - 1, col, value)
        flood_fill(matrix, row + 1, col, value)
        flood_fill(matrix, row, col - 1, value)
        flood_fill(matrix, row, col + 1, value)

    n = len(nums) - 1
    visited = [[0]*n for _ in range(n)]
    for start in range(n):
        for end in range(start + 1, n + 1):
            if nums[start] == nums[end]:
                value = nums[start]
                for i in range(len(visited)):
                    visited[i][start] = -1 if i == start else value if i == end else 0
                for i in range(len(visited)):
                    visited[i][end] = -1 if i == end else value if i == start else 0
                found = True
                for line in visited:
                    for x in line:
                        if x!= -1:
                            found = False
                            break
                    if not found:
                        break
                if found:
                    return value

    for i, num in enumerate(nums):
        flood_fill(visited, i, i, num)
    visited[0][0] = -1

    find = (0, 0)
    while True:
        minx, miny = float('inf'), float('inf')
        maxx = miny = 0
        for x in range(len(visited)):
            for y in range(len(visited[0])):
                if visited[x][y]!= -1:
                    if x < minx:
                        minx, miny = x, y
                    if y < miny:
                        miny = y
                    if x > maxx:
                        maxx, maxy = x, y
                    if y > maxy:
                        maxy = y
        if maxx == minx and maxy == 0:
            break
        x, y = maxx, maxy
        value = visited[x][y]
        visited[x][y] = -1
        for i in range(abs(x - minx) + 1):
            if visited[minx + i][miny] < 0:
                continue
            visited[minx + i][miny] = value
        for i in range(abs(x - minx) + 1):
            if visited[minx + i][maxy] < 0:
                continue
            visited[minx + i][maxy] = value

    for i, num in enumerate(nums):
        if visited[i][i] == num:
            return num
